	{SarvamEvent: "SessionStart", HookName: "session-start", EntryName: "entire-session-start", EventType: 1},
	{SarvamEvent: "UserPromptSubmit", HookName: "user-prompt-submit", EntryName: "entire-user-prompt-submit", EventType: 2},
