	{SarvamEvent: "PreCompact", HookName: "pre-compact", EntryName: "entire-pre-compact", EventType: 4},
	{SarvamEvent: "PostCompact", HookName: "post-compact", EntryName: "entire-post-compact", EventType: 4},
}

