	return []tomlBlock{
		{header: fmt.Sprintf("[[hooks.%s]]", event)},
		{header: fmt.Sprintf("[[hooks.%s.hooks]]", event), body: []string{
			"type = \"command\"",
			fmt.Sprintf("command = %s", encodeTOMLString(command)),
