		if text == "" || isHarnessContext(text) {
			return nil
		}
		return []any{wireMessage{
			Role:    "user",
			Content: []any{wireTextBlock{Type: "text", Text: text}},
		}}
	case "assistant":
		text := messageText(message, "output_text")
		if strings.TrimSpace(text) == "" {
			return nil
		}
		return []any{wireMessage{
			Role:    "assistant",
			Content: []any{wireTextBlock{Type: "text", Text: text}},
		}}
