}

func (f *rolloutFixture) write(t *testing.T) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "rollout-test.jsonl")
	joined := ""
	for _, line := range f.lines {
		joined += line + "\n"
	}
	if err := os.WriteFile(path, []byte(joined), 0o600); err != nil {
		t.Fatal(err)
	}
	return path
}

func sampleRollout(t *testing.T) string {
	t.Helper()
	f := &rolloutFixture{}
	f.add(`{"timestamp":"2026-11-16T05:59:59.000Z","type":"session_meta","payload":{"id":"s-1","cwd":"/repo","source":"cli"}}`)
	f.user("<environment_context>\n  <cwd>/repo</cwd>\n</environment_context>")
	f.user("Create hello.txt with the word hello")
	f.assistant("I'll create the file now.")
	f.functionCall("write_file", "call-1", `{"contents":"hello","path":"hello.txt"}`)
	f.add(`{"timestamp":"2026-11-16T06:00:02.500Z","type":"response_item","payload":{"type":"function_call_output","call_id":"call-1","output":"{\"output\":\"Success\",\"metadata\":{\"exit_code\":0}}"}}`)
	f.functionCall("exec_command", "call-2", `{"cmd":"echo x > notes.md && touch readme.md","command":"echo x > notes.md && touch readme.md"}`)
	f.assistant("done")
	return f.write(t)
}

